   -> /// The `(string)` cast is what makes `$line` a STRING rather than `string|false`, and it is
/// also php's own answer: `(string) false` is `""`. Keeping the union instead left `fscanf()`
/// handing a boxed Mixed to `sscanf()`'s declared `string` parameter.
fn spl_file_object_read_line_stmts() -> Vec<Stmt> {
    vec![assign_stmt(
        "line",
        cast_expr(
            CastType::Str,
            function_call("fgets", vec![file_stream_expr()]),
        ),
    )]
}
